def check_good_triple(x, y, z):
    """Checks if (x+1)^y / (x^z + 1) is an integer."""
    try:
        numerator = (x + 1)**y
        denominator = x**z + 1

        # Check for integer division
        if denominator == 0:
            return False # Should not happen since x, z >= 1

        if numerator % denominator == 0:
            return True, numerator // denominator
        else:
            return False, None
    except OverflowError:
        # Handle potential large numbers, though for x, y, z <= 5 this should be fine.
        return False, None

good_triples = []
for x in range(1, 6):
    for y in range(1, 6):
        for z in range(1, 6):
            is_good, result = check_good_triple(x, y, z)
            if is_good:
                good_triples.append((x, y, z))

print(f"Good triples found: {good_triples}")

